/// <summary>
/// A handheld's report at the end of an item sync - see HSMobileOpsSkuPageService::reportSync.
/// Succeeded with the counts, or not with the error Message.
/// </summary>
[DataContractAttribute]
class HSMobileOpsSkuSyncReport
{
    str dataAreaId;
    str deviceId;
    str warehouse;
    str scope;
    boolean succeeded;
    boolean full;
    int items;
    int barcodes;
    int seconds;
    str message;
    str appVersion;
}

Method.Source:
[DataMemberAttribute('DataAreaId')]
public str parmDataAreaId(str _value = dataAreaId)
{
    dataAreaId = _value;
    return dataAreaId;
}

[DataMemberAttribute('DeviceId')]
public str parmDeviceId(str _value = deviceId)
{
    deviceId = _value;
    return deviceId;
}

[DataMemberAttribute('Warehouse')]
public str parmWarehouse(str _value = warehouse)
{
    warehouse = _value;
    return warehouse;
}

[DataMemberAttribute('Scope')]
public str parmScope(str _value = scope)
{
    scope = _value;
    return scope;
}

[DataMemberAttribute('Succeeded')]
public boolean parmSucceeded(boolean _value = succeeded)
{
    succeeded = _value;
    return succeeded;
}

[DataMemberAttribute('Full')]
public boolean parmFull(boolean _value = full)
{
    full = _value;
    return full;
}

[DataMemberAttribute('Items')]
public int parmItems(int _value = items)
{
    items = _value;
    return items;
}

[DataMemberAttribute('Barcodes')]
public int parmBarcodes(int _value = barcodes)
{
    barcodes = _value;
    return barcodes;
}

[DataMemberAttribute('Seconds')]
public int parmSeconds(int _value = seconds)
{
    seconds = _value;
    return seconds;
}

[DataMemberAttribute('Message')]
public str parmMessage(str _value = message)
{
    message = _value;
    return message;
}

[DataMemberAttribute('AppVersion')]
public str parmAppVersion(str _value = appVersion)
{
    appVersion = _value;
    return appVersion;
}
